package ru.neverland.townysieges;
import java.time.*;
public final class RaidWindowSmoke {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}static long at(String instant){return Instant.parse(instant).toEpochMilli();}public static void main(String[] args){ZoneId moscow=ZoneId.of("Europe/Moscow");var evening=new RaidWindow(18*60,23*60);check(evening.fits(at("2026-10-28T16:00:00Z"),3600000,moscow),"inside Moscow hours");check(!evening.fits(at("2026-10-28T19:59:59Z"),3600000,moscow),"whole preparation and fight must fit");check(!evening.fits(at("2026-10-28T12:00:00Z"),3600000,moscow),"closed before opening");var night=new RaidWindow(22*60,4*60);check(night.fits(at("2026-10-28T22:00:00Z"),3600000,moscow),"cross-midnight after midnight");check(!night.fits(at("2026-10-29T01:00:00Z"),1,moscow),"close boundary exclusive");check(new RaidWindow(0,0).fits(at("2026-10-28T00:00:00Z"),86400000,moscow),"legacy all-day default");ZoneId berlin=ZoneId.of("Europe/Berlin");var dst=new RaidWindow(0,4*60);check(dst.fits(at("2026-10-25T00:30:00Z"),7200000,berlin),"actual autumn zone transition");check(!dst.fits(at("2026-03-29T00:30:00Z"),7200000,berlin),"spring shortened interval");check(RaidWindow.minute("18:30")==1110,"minute precision");System.out.println("RaidWindowSmoke PASS: full battle duration, Moscow, midnight, boundaries and both DST transitions");}
}
